using System.Text.Json;
using System.Text.RegularExpressions;

namespace LeoGRpcApi.Shared.ApiContract.Validation;

/// <summary>
///     Naming conventions shared by FluentValidation and the protobuf contract, so that the field names in a
///     validation error match the field names the other side of the call knows
/// </summary>
internal static partial class ValidationNaming
{
    /// <summary>
    ///     Converts a property name to the lowerCamelCase form used in the protobuf contract
    /// </summary>
    /// <param name="memberName">The name of the property as generated by protoc</param>
    /// <returns>The field name as it appears in the protobuf contract</returns>
    public static string ToPropertyName(string memberName) => JsonNamingPolicy.CamelCase.ConvertName(memberName);

    /// <summary>
    ///     Converts a property name to the human-readable display name used inside validation messages
    /// </summary>
    /// <param name="memberName">The name of the property as generated by protoc</param>
    /// <returns>The display name to use in validation messages</returns>
    public static string ToDisplayName(string memberName) => PascalCaseBoundary.Replace(memberName, " $1");

    [GeneratedRegex("(?<=[a-z0-9])([A-Z])")]
    private static partial Regex PascalCaseBoundary { get; }
}
